@module timing  src=timing.lua  loc=412  mode=namespace  self=timing

# Invariants & contracts
  @invariant  pure module — no module-level state; all functions take operands explicitly  @ 4
  @invariant  two frames: ppqL (logical) and raw ppq (realisation); forward only — ppq = fromLogical(ppqL) + delayToPPQ(delay), endppq = fromLogical(endppqL); see docs/timing.md  @ 5
  @invariant  atoms are pure (u, shift) functions on the unit interval; inverse via Newton (closed form for id)  @ 6
  @invariant  tile period unit is QN (quarter notes); period may be scalar or {num,den}  @ 7
  @invariant  factor order is inner-to-outer: applyFactors walks forward, unapplyFactors walks backward  @ 8
  @invariant  K is the max stretch factor; bounded atoms have posRange/negRange = max |s| (per sign) keeping slope ∈ [1/K, K]  @ 9

# Shapes
  @shape  Atom = { forward = fn(u, shift) -> v, inverse = fn(v, shift) -> u }  @ 10
  @shape  Factor = { atom = string, shift = number_qn, period = number|{num,den}, phase? = number_qn|{num,den} }  @ 11
  @shape  Composite = { phase? = number_qn|{num,den}, factors = Factor[] }   -- bare {} or {factors={}} both denote identity  @ 12
  @shape  ResolvedFactor = { atom = string, shift = number_unit, T = number_ppq, phase? = number_ppq }  @ 13
  @shape  Shape = { factors, a, b, ya, yb, length, identity? }   -- linear ramps on [0,a] and [b,length]; analytic middle on (a,b)  @ 14
  @shape  AtomMeta = { posRange = number, negRange = number, pulsesPerCycle = 1|2 }  @ 15

# Imports
  @const util = 'util'  @ 16

# Module-level constants
  @const timing = {}  @ 18
  @const PI = math.pi  @ 35
  @const TAU = 2 * PI  @ 36
  @const SHUFFLE_K = 2 / (3 * math.sqrt(3))  @ 37   -- pins |g| = 1 at the extrema
  @const TOL = 1e-12  @ 38
  @const MAX_ITER = 20  @ 39
  @const K = timing.K  @ 129
  @const PERIOD_TERM_MAX = 999  @ 172

# Private functions
  -- Atoms
  @fn newton(fwd, dfwd, v, s)  @ 47-59
      -- Bracket-augmented Newton on smooth f mapping [0,1] → [0,1]: maintain
      -- [lo, hi] bracketing the root by sign of the residual; fall back to
      -- bisection whenever a Newton step leaves the bracket. Pure Newton
      -- overshoots near slope-min regions (slope → 1/K at the K-bound limit);
      -- bracketing forces global convergence while preserving the quadratic
      -- end-game once Newton stops escaping.
  @fn smooth(g, gp)  @ 62-69
      -- Build a smooth atom from g(u) and g'(u). f(u, s) = u + s·g(u).
  -- Period helpers
  @fn reducedPeriod(num, den)  @ 165-168
      -- A period in lowest terms, so a typed 6/8 and the ladder's 3/4 are one value --
      -- the widget matches by equality, and an unreduced twin would read as off-ladder.
  @fn stepFine(ladder, cur, dir)  @ 208-221
      -- The ladder descends: shortening takes the first entry below the current QN, lengthening the
      -- last one above it. Comparing QN, not list position, lets an off-ladder period enter between neighbours.
  @fn stepCoarse(ladder, cur, dir)  @ 225-236
      -- Coarse aims at half or double and takes the nearest entry, measured as a ratio since the ladder
      -- is geometric. Candidates are restricted to the arrow's side, so a coarse step can't double back.
  -- Factor resolution
  -- Tile bookkeeping
  @fn tileApply(rf, p)  @ 286-293
      -- f(u, s) lifted to a tile of period T with optional phase.
  @fn tileUnapply(rf, p)  @ 295-302
  -- Composite resolution
  @fn findRampOn(factors, length, step)  @ 328-338
  @fn findRampOff(factors, length, step)  @ 340-350
  @fn identityShape(length)  @ 352-354

# Functions held in tables
  @held id.forward(u, s)  @ 77
  @held id.inverse(v, s)  @ 78

# Handlers registered
  @handler table:sort(a, b)  @ 185

# Public API (timing.*)
  @api timing.atomTilePeriod(factor)  @ 142-144
      @contract  returns QN, not PPQ; multiply by resolution at the swing-resolution boundary  @ 141
  @api timing.isIdentity(composite)  @ 147-151
      @contract  bare {} treated as identity; either missing factors or empty factors with zero phase counts  @ 146
  @api timing.periodQN(period)  @ 156-161
      -- Bad shape is a caller bug; fail loudly rather than guessing.
  @api timing.formatPeriod(period)  @ 189-193
      @contract  period -> its bare-fraction text; a whole QN drops the denominator  @ 188
  @api timing.parsePeriod(text)  @ 196-204
      @contract  text -> a reduced {num,den}, or nil where it names no period  @ 195
  @api timing.steppedPeriod(ladder, period, dir, coarse)  @ 239-243
      @contract  ladder entry one step from `period`; dir 1 shortens, coarse halves/doubles, nil at end  @ 238
  @api timing.compositePeriodQN(composite)  @ 247-260
      -- Uses internal tile periods (period × pulsesPerCycle), so the result is
      -- the realised repeat rate, not the user-period.
  @api timing.resolveFactors(composite, ppqPerQN)  @ 265-281
      @contract  Composite + ppqPerQN -> ResolvedFactor[]; folds composite.phase into each factor's effective phase. Sole pre-flight for applyFactors / unapplyFactors and resolveComposite.  @ 264
  @api timing.applyFactors(factors, ppq)  @ 305-308
      @contract  ppqL -> ppqI; identity-safe on empty factors  @ 304
  @api timing.unapplyFactors(factors, ppq)  @ 311-314
      @contract  ppqI -> ppqL; reverses factor order to invert composition  @ 310
  @api timing.resolveComposite(composite, length, ppqPerQN)  @ 357-368
      @contract  identity composite or length≤0 returns an identity-Shape sentinel; otherwise returns Shape{factors, a, b, ya, yb, length}. Consumers eval/invert across both forms.  @ 356
  @api timing.eval(S, x)  @ 371-380
      @contract  eval routes by x: ramp-on for x≤a, applyFactors for a<x<b, ramp-off for x≥b  @ 370
  @api timing.invert(S, y)  @ 383-392
      @contract  invert routes by y: ramp-on inverse for y≤ya, unapplyFactors for ya<y<yb, ramp-off inverse for y≥yb  @ 382
  -- Logical grid
  @api timing.logPerRow(rpb, denom, resolution)  @ 397-399
      @contract  callers must store result as float; tv relies on unrounded ppqs for swing-inversion exactness  @ 396
  -- Delay <-> PPQ
  @api timing.delayToPPQ(d, res)  @ 404-406
      @contract  d in signed milli-QN, res in PPQ/QN; nil d treated as 0  @ 403
  @api timing.ppqToDelay(p, res)  @ 408-410

